export function DocumentViewer({
  title = "{{title}}",
  page = "{{page}}",
  zoom = "{{zoom}}",
  accent = "{{accent}}",
}) {
  const pagePad = zoom === "150%" ? "30px 18px" : "20px 18px";
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", width: 300, borderRadius: 10, overflow: "hidden", boxSizing: "border-box", border: "1px solid #24143018" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "8px 12px", fontWeight: 700, color: "#14351f", background: accent }}>
        <span>{title}</span>
        <span>{zoom}</span>
      </div>
      <div style={{ background: "#24143008", padding: pagePad, minHeight: 90 }}>
        <span style={{ display: "block", height: 8, background: "#24143022", borderRadius: 4, marginBottom: 8 }} />
        <span style={{ display: "block", height: 8, background: "#24143022", borderRadius: 4, marginBottom: 8 }} />
        <span style={{ display: "block", height: 8, background: "#24143022", borderRadius: 4, marginBottom: 8, width: "60%" }} />
      </div>
      <p style={{ margin: 0, padding: "8px 12px", fontSize: 12, color: "#24143099", textAlign: "center" }}>Page {page} of 8</p>
    </div>
  );
}
